The rank-collapse hypothesis was rejected — A and C have essentially identical spectra. However, the delta pattern is consistent: **C shifts roughly 1.5× more than A** in every block and every layer type, and C also has the greater norm increase (especially out_proj and fc2). Next, independent discrimination tests: (g) effective rank of the *delta* matrix (the CIFAR-100 token stream is a low-dimensional blur → gradient/delta should be low-rank), (k) decomposition of the delta into shrinkage vs. orthogonal components, (a) per-head QK "temperature" (sharpness of attention), and per-head delta concentration.

```python
def eff_rank(s2, p=1e-300):
    e = s2/e.sum(); 
    return float(np.exp(-(e*np.log(e+p)).sum()))

print("== effective rank of DELTA matrices (X-B), mean over blocks ==")
for t in ['attn.in_proj_weight','attn.out_proj.weight','mlp.fc1.weight','mlp.fc2.weight']:
    row = f"{t:24s} "
    for m in 'AC':
        er, t16, t64 = [], [], []
        for b in blocks:
            D = weights[m][f"{b}.{t}"].astype(np.float64) - weights['B'][f"{b}.{t}"].astype(np.float64)
            s = np.linalg.svd(D, compute_uv=False)
            e = s**2
            er.append(eff_rank(e)); t16.append((e[:16]/e.sum()).sum()); t64.append((e[:64]/e.sum()).sum())
        row += f" {m}: erg={np.mean(er):6.1f} t16={np.mean(t16):.3f} t64={np.mean(t64):.3f}  |"
    print(row)

print("\n== delta decomposition: delta = alpha*B + perp  (alpha>0 growth, <0 shrink) ==")
for t in ['attn.in_proj_weight','attn.out_proj.weight','mlp.fc1.weight','mlp.fc2.weight','attn.in_proj_bias','mlp.fc1.bias']:
    row = f"{t:24s} "
    for m in 'AC':
        alphas, perps = [], []
        for b in blocks:
            Wb = weights['B'][f"{b}.{t}"].ravel().astype(np.float64)
            d = weights[m][f"{b}.{t}"].ravel().astype(np.float64) - Wb
            a = d.dot(Wb)/Wb.dot(Wb)
            alphas.append(a); perps.append(np.linalg.norm(d - a*Wb)/np.linalg.norm(Wb))
        row += f" {m}: alpha={np.mean(alphas):+.5f} perp={np.mean(perps):.4f}  |"
    print(row)

print("\n== per-head QK temperature (||Wq^T Wk||_F/64, mean over blocks) and V norm ==")
for m in 'BAC':
    temps, vnorms = [], []
    for b in blocks:
        W = weights[m][f"{b}.attn.in_proj_weight"].astype(np.float64)
        Q,K,Vv = W[:768].reshape(12,64,768), W[768:1536].reshape(12,64,768), W[1536:].reshape(12,64,768)
        for h in range(12):
            t = np.linalg.norm(Q[h].T @ K[h])/64.0
            temps.append(t)
        vnorms.append(np.linalg.norm(Vv)/768.0)
    print(f"{m}: QK temp mean={np.mean(temps):.5f} min={np.min(temps):.5f} max={np.max(temps):.5f} |V|/768={np.mean(vnorms):.4f}")

print("\n== per-head delta in in_proj (Q,K,V subblocks), mean over blocks: max head / mean head ==")
for m in 'AC':
    for part,sl in [('Q',slice(0,768)),('K',slice(768,1536)),('V',slice(1536,2304))]:
        hs = []
        for b in blocks:
            Da = (weights[m][f"{b}.attn.in_proj_weight"].astype(np.float64)-weights['B'][f"{b}.attn.in_proj_weight"].astype(np.float64))[sl].reshape(12,64,768)
            hb = [np.linalg.norm(Da[h]) for h in range(12)]
            hs.append((max(hb)/np.mean(hb)))
        print(f"{m} {part}: maxhead/meanhead = {np.mean(hs):.2f}")
